package markdown

import (
    "fmt"
    "strings"
)

// Render translates markdown to HTML.
//
// The document is processed line by line. Each line is either a
// header, a list item, or plain text; consecutive plain-text lines
// are wrapped in a single <p> element.
func Render(markdown string) string {
    // Inline emphasis markers are translated before line parsing,
    // matching the original implementation's behavior.
    markdown = applyEmphasis(markdown)

    var html strings.Builder
    inList := false
    var paragraph strings.Builder

    flushParagraph := func() {
        if paragraph.Len() > 0 {
            html.WriteString("<p>" + paragraph.String() + "</p>")
            paragraph.Reset()
        }
    }

    for _, line := range strings.Split(markdown, "\n") {
        switch {
        case isListLine(line):
            flushParagraph()
            if !inList {
                html.WriteString("<ul>")
                inList = true
            }
            html.WriteString("<li>" + strings.TrimPrefix(line, "* ") + "</li>")
        case isHeaderLine(line):
            flushParagraph()
            if inList {
                html.WriteString("</ul>")
                inList = false
            }
            level, text := parseHeader(line)
            html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", level, text, level))
        default:
            if inList {
                html.WriteString("</ul>")
                inList = false
            }
            if paragraph.Len() > 0 {
                paragraph.WriteString("\n")
            }
            paragraph.WriteString(line)
        }
    }
    flushParagraph()
    if inList {
        html.WriteString("</ul>")
    }
    return html.String()
}
```

